-- Commercial primary tax identification; no bulk updates to existing answers or files.
-- Legacy personal IDs remain identifiable and require explicit correction before submission.
begin;
alter table public.glf_kyc_cases alter column form_version set default '2026-10-27.5';
create or replace function glf_kyc_private.fields() returns jsonb language sql immutable set search_path='' as $fields$ select '[{"key":"relation","label":["¿Cuál es su vínculo con GLF?","What is your relationship with GLF?"],"step":0,"required":true,"type":"select","options":["supplier","consultant","staff","board"],"help":["Primero confirme el vínculo indicado por Carolina. Equipo y Directorio no se incorporan al directorio de proveedores.","Confirm the relationship selected by Carolina. Staff and board members are not added to the supplier directory."]},{"key":"nationalityType","label":["Condición de la contratación","Engagement location"],"step":0,"required":true,"type":"select","when":{"relation":["supplier","consultant"]},"options":["national","international"]},{"key":"person","label":["¿En nombre de quién presenta el formulario?","On whose behalf are you completing this form?"],"step":0,"required":true,"type":"select","when":{"relation":["supplier","consultant"]},"options":["natural","legal"],"help":["Tener RUC no convierte a una persona natural en compañía. Seleccione persona jurídica solo si contrata la entidad.","A tax ID does not make an individual a company. Select legal entity only when the entity is the contracting party."]},{"key":"country","label":["País de emisión o constitución","Country of issue / incorporation"],"step":1,"required":true,"type":"country"},{"key":"idType","label":["Tipo de identificación","Identification type"],"step":1,"required":true,"type":"document"},{"key":"id","label":["Número de identificación","Identification number"],"step":1,"required":true,"type":"text","max":60},{"key":"name","label":["Nombre completo / razón social","Full name / registered name"],"step":1,"required":true,"type":"text"},{"key":"birthDate","label":["Fecha de nacimiento","Date of birth"],"step":1,"required":true,"type":"date","when":{"person":["natural"]}},{"key":"incorporationDate","label":["Fecha de constitución","Date of incorporation"],"step":1,"required":true,"type":"date","when":{"person":["legal"]}},{"key":"nationality","label":["Nacionalidad","Nationality"],"step":1,"required":true,"type":"text","when":{"person":["natural"]}},{"key":"birthCountry","label":["País de nacimiento","Country of birth"],"step":1,"required":true,"type":"country","when":{"person":["natural"]}},{"key":"billingEmailSame","label":["Usar el correo de contacto para facturación","Use contact email for billing"],"step":1,"required":false,"type":"select","when":{"person":["legal"]},"options":["yes","no"]},{"key":"billingEmail","label":["Correo para facturación","Billing email"],"step":1,"required":false,"type":"email","when":{"person":["legal"],"billingEmailSame":["no"]}},{"key":"phoneAdditional","label":["Teléfono adicional","Additional phone"],"step":1,"required":false,"type":"tel","max":50,"help":["Incluya el código de país, por ejemplo +593 991234567.","Include the country calling code, e.g. +593 991234567."]},{"key":"email","label":["Correo electrónico","Email"],"step":1,"required":true,"type":"email"},{"key":"phone","label":["Teléfono principal","Primary phone"],"step":1,"required":true,"type":"tel","max":50},{"key":"residenceCountry","label":["País de domicilio","Country of residence"],"step":1,"required":true,"type":"country"},{"key":"city","label":["Ciudad de domicilio","City of residence"],"step":1,"required":true,"type":"text"},{"key":"address","label":["Dirección de domicilio","Residential / registered address"],"step":1,"required":true,"type":"text","max":1000},{"key":"activity","label":["Actividad económica o profesional","Economic or professional activity"],"step":2,"required":true,"type":"textarea","when":{"relation":["supplier","consultant"]},"max":2000},{"key":"services","label":["Bienes o servicios que prestará al GLF","Goods or services you will provide to GLF"],"step":2,"required":true,"type":"textarea","when":{"relation":["supplier","consultant"]},"max":2000},{"key":"website","label":["Sitio web (opcional)","Website (optional)"],"step":2,"required":false,"type":"text","when":{"relation":["supplier","consultant"]}},{"key":"monthlyIncome","label":["Ingresos mensuales estimados (USD)","Estimated monthly income (USD)"],"step":2,"required":true,"type":"number","when":{"relation":["supplier","consultant"]}},{"key":"monthlyExpenses","label":["Egresos mensuales estimados (USD)","Estimated monthly expenses (USD)"],"step":2,"required":true,"type":"number","when":{"relation":["supplier","consultant"]}},{"key":"bankCountry","label":["País de la entidad financiera","Financial institution country"],"step":2,"required":true,"type":"country","when":{"relation":["supplier","consultant"]}},{"key":"bankName","label":["Entidad financiera","Financial institution"],"step":2,"required":true,"type":"bank","when":{"relation":["supplier","consultant"]},"help":["Seleccione la entidad o use Otra / No encuentro mi entidad. Copie el nombre como figura en el certificado bancario.","Select the institution or use Other / Institution not listed. Use the name shown on the bank certificate."]},{"key":"bankHolder","label":["Titular de la cuenta","Account holder"],"step":2,"required":true,"type":"text","when":{"relation":["supplier","consultant"]}},{"key":"bankAccount","label":["Número de cuenta / IBAN","Account number / IBAN"],"step":2,"required":true,"type":"text","when":{"relation":["supplier","consultant"]},"max":100},{"key":"role","label":["Cargo o función en GLF","Position or role at GLF"],"step":2,"required":true,"type":"text","when":{"relation":["staff","board"]}},{"key":"employer","label":["Entidad empleadora / ocupación actual","Current employer / occupation"],"step":2,"required":false,"type":"text","when":{"relation":["staff","board"]}},{"key":"legalRep","label":["Nombre del representante legal","Legal representative name"],"step":3,"required":true,"type":"text","when":{"person":["legal"]}},{"key":"legalRepIdType","label":["Tipo de documento del representante legal","Legal representative document type"],"step":3,"required":true,"type":"select","when":{"person":["legal"]},"options":["cedula","ruc","passport","foreign_id"],"help":["Documento de la persona que representa a la entidad. El RUC de la entidad se registra en Identidad.","Document of the individual representing the entity. The entity tax registration is recorded in Identity."]},{"key":"legalRepId","label":["Número de documento del representante legal","Legal representative document number"],"step":3,"required":true,"type":"text","when":{"person":["legal"]},"max":60},{"key":"legalRepCountry","label":["País de emisión del documento del representante","Representative ID issuing country"],"step":3,"required":true,"type":"country","when":{"person":["legal"]}},{"key":"ownershipExplanation","label":["Si no existen socios declarables, explique la estructura","If there are no reportable owners, explain the structure"],"step":3,"required":false,"type":"textarea","when":{"person":["legal"]},"max":2000},{"key":"controllers","label":["Personas con control sin participación (si corresponde; para revisión)","Persons with control without ownership (if applicable; for review)"],"step":3,"required":false,"type":"textarea","when":{"person":["legal"]},"max":2000,"help":["La obligación documental de estas personas está pendiente de validación por Carolina.","Document requirements for these persons remain subject to Carolina’s confirmation."]},{"key":"spouse","label":["¿Tiene cónyuge o conviviente?","Do you have a spouse or partner?"],"step":3,"required":true,"type":"select","when":{"person":["natural"]},"options":["yes","no"]},{"key":"spouseName","label":["Nombre del cónyuge o conviviente","Spouse / partner name"],"step":3,"required":true,"type":"text","when":{"person":["natural"],"spouse":["yes"]}},{"key":"spouseIdType","label":["Tipo de documento del cónyuge o conviviente","Spouse / partner document type"],"step":3,"required":true,"type":"select","when":{"person":["natural"],"spouse":["yes"]},"options":["cedula","ruc","passport","foreign_id"]},{"key":"spouseId","label":["Número de documento del cónyuge o conviviente","Spouse / partner document number"],"step":3,"required":true,"type":"text","when":{"person":["natural"],"spouse":["yes"]},"max":60},{"key":"spouseCountry","label":["País de emisión del documento del cónyuge o conviviente","Spouse / partner document issuing country"],"step":3,"required":true,"type":"country","when":{"person":["natural"],"spouse":["yes"]}},{"key":"pepSelf","label":["¿Es usted una persona expuesta políticamente (PEP)?","Are you a politically exposed person (PEP)?"],"step":4,"required":true,"type":"select","options":["yes","no","unsure"]},{"key":"pepSelfPosition","label":["Cargo que ejerce o ejerció","Position held now or previously"],"step":4,"required":true,"type":"text","when":{"pepSelf":["yes","unsure"]}},{"key":"pepSelfInstitution","label":["Institución u organismo del cargo","Institution or organization of the position"],"step":4,"required":true,"type":"text","when":{"pepSelf":["yes","unsure"]}},{"key":"pepSelfCountry","label":["País del cargo público","Country of public position"],"step":4,"required":true,"type":"country","when":{"pepSelf":["yes","unsure"]}},{"key":"pepCurrent","label":["¿Ejerce actualmente ese cargo?","Do you currently hold this position?"],"step":4,"required":true,"type":"select","when":{"pepSelf":["yes","unsure"]},"options":["yes","no"]},{"key":"pepEndDate","label":["Fecha de finalización del cargo","Date the position ended"],"step":4,"required":true,"type":"date","when":{"pepSelf":["yes","unsure"],"pepCurrent":["no"]}},{"key":"pepFamily","label":["¿Tiene un familiar PEP?","Do you have a family member who is a PEP?"],"step":4,"required":true,"type":"select","options":["yes","no"]},{"key":"pepName","label":["Nombre del familiar PEP","PEP family member name"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepRelation","label":["Parentesco","Family relationship"],"step":4,"required":true,"type":"kinship","when":{"pepFamily":["yes"]}},{"key":"pepRelationOther","label":["Indique el parentesco","Specify the relationship"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"],"pepRelation":["other"]}},{"key":"pepPosition","label":["Cargo del familiar PEP","PEP family member position"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepInstitution","label":["Institución del familiar PEP","PEP family member institution"],"step":4,"required":true,"type":"text","when":{"pepFamily":["yes"]}},{"key":"pepCountry","label":["País del familiar PEP","PEP family member country"],"step":4,"required":true,"type":"country","when":{"pepFamily":["yes"]}},{"key":"pepRelatives","label":["Otros familiares PEP","Additional PEP relatives"],"step":4,"required":false,"type":"pepRelatives","when":{"pepFamily":["yes"]},"max":20000},{"key":"glfFamily","label":["¿Tiene familiares que trabajen o integren el GLF?","Do you have relatives working for or serving on GLF?"],"step":4,"required":true,"type":"select","options":["yes","no"]},{"key":"glfFamilyDetail","label":["Nombre, parentesco y función en GLF","Name, relationship and GLF role"],"step":4,"required":true,"type":"textarea","when":{"glfFamily":["yes"]},"max":2000},{"key":"glfRelatives","label":["Otros familiares en GLF","Additional relatives at GLF"],"step":4,"required":false,"type":"glfRelatives","when":{"glfFamily":["yes"]},"max":20000},{"key":"incomeSources","label":["Fuentes principales de ingresos y recursos","Main sources of income and resources"],"step":4,"required":true,"type":"sources","when":{"relation":["supplier","consultant"]},"max":1000},{"key":"funds","label":["¿De dónde provienen sus ingresos y recursos?","Where do your income and resources come from?"],"step":4,"required":true,"type":"textarea","when":{"relation":["supplier","consultant"]},"max":2000,"help":["Describa brevemente las fuentes principales. No necesita repetir los montos mensuales. Ejemplo: ingresos por consultorías ambientales y arrendamiento de un inmueble.","Briefly describe the main sources. Do not repeat monthly amounts. Example: environmental consulting fees and rental income."]},{"key":"lawfulFunds","label":["Declaración de origen lícito de fondos","Declaration of lawful source of funds"],"step":4,"required":true,"type":"consent","options":["yes"]},{"key":"verificationConsent","label":["Autorización para las verificaciones KYC","Authorization for KYC checks"],"step":4,"required":true,"type":"consent","options":["yes"]},{"key":"missingInformation","label":["Datos o documentos que no puede proporcionar y motivo","Information or documents you cannot provide and reason"],"step":5,"required":false,"type":"textarea","max":4000},{"key":"truth","label":["Confirmo que la información es completa y veraz","I confirm that the information is complete and accurate"],"step":4,"required":true,"type":"consent","options":["yes"]}]'::jsonb $fields$;
create or replace function glf_kyc_private.project(p jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare a jsonb:=p;r jsonb:='{}';f jsonb;o jsonb;owners jsonb:='[]';
begin
 if a->>'relation' in('staff','board') then a=jsonb_set(a,'{person}','"natural"');end if;
 if a->>'relation' in('supplier','consultant') then
  if a->>'idType' in('cedula','passport','foreign_id') and trim(coalesce(a->>'id',''))<>'' then
   if trim(coalesce(a->>'taxId',''))<>'' then
    a=jsonb_set(a,'{id}',to_jsonb(trim(a->>'taxId')));
    a=jsonb_set(a,'{idType}',to_jsonb(case when a->>'country'='EC' then 'ruc' else 'tax_id' end));
   end if;
  else a=jsonb_set(a,'{idType}',to_jsonb(case when a->>'country'='EC' then 'ruc' else 'tax_id' end));end if;
 elsif a->>'country'='EC' then a=jsonb_set(a,'{idType}','"cedula"');
 elsif coalesce(a->>'idType','') not in('passport','foreign_id') then a=jsonb_set(a,'{idType}','"passport"');end if;
 for f in select value from jsonb_array_elements(glf_kyc_private.fields()) loop
 if glf_kyc_private.applies(f,a) then r=r||jsonb_build_object(f->>'key',trim(coalesce(a->>(f->>'key'),'')));end if;end loop;
 if a->>'person'='legal' and jsonb_typeof(a->'owners')='array' then
 for o in select value from jsonb_array_elements(a->'owners') limit 30 loop owners=owners||jsonb_build_array(jsonb_build_object('name',trim(coalesce(o->>'name','')),'pct',coalesce(o->>'pct',''),'country',trim(coalesce(o->>'country','')),'id',trim(coalesce(o->>'id','')),'idType',trim(coalesce(o->>'idType',''))));end loop;end if;
 return r||jsonb_build_object('person',coalesce(a->>'person',''),'owners',owners);
end;$$;


create or replace function glf_kyc_private.validate(p jsonb) returns text[] language plpgsql stable set search_path='' as $$
declare a jsonb:=glf_kyc_private.project(p);f jsonb;v text;errs text[]:='{}';o jsonb;total numeric:=0;
begin
 for f in select value from jsonb_array_elements(glf_kyc_private.fields()) loop
 if not glf_kyc_private.applies(f,a) then continue;end if;v=coalesce(a->>(f->>'key'),'');
 if (coalesce((f->>'required')::boolean,false) and v='') or length(v)>coalesce((f->>'max')::integer,250) or (v<>'' and f ? 'options' and not (f->'options' ? v)) then errs=array_append(errs,f->>'key');end if;
 if f->>'type' in('sources','pepRelatives','glfRelatives') and not glf_kyc_private.review_list_valid(v,f->>'type') then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='kinship' and v<>'' and v !~ '^[^<>]{1,100}$' then errs=array_append(errs,f->>'key');end if;
 if v<>'' then
 if f->>'type'='email' and v !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='tel' and (v !~ '[0-9]' or v !~ '^[+0-9(). -]+$') then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='country' and v !~ '^[A-Z]{2}$' then errs=array_append(errs,f->>'key');end if;
 if f->>'type'='number' then if v !~ '^[0-9]+(\.[0-9]{1,2})?$' then errs=array_append(errs,f->>'key');elsif v::numeric>999999999999.99 then errs=array_append(errs,f->>'key');end if;end if;
 if f->>'type'='date' and (v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or v>current_date::text) then errs=array_append(errs,f->>'key');end if;
 end if;end loop;
 if a->>'relation' in('supplier','consultant') then
  if a->>'idType'<>(case when a->>'country'='EC' then 'ruc' else 'tax_id' end) then errs=array_append(errs,'idType');end if;
 elsif a->>'country'='EC' then
  if a->>'idType'<>'cedula' then errs=array_append(errs,'idType');end if;
 elsif a->>'idType' not in('passport','foreign_id') then errs=array_append(errs,'idType');end if;
 if a->>'country'='EC' and ((a->>'idType'='ruc' and a->>'id' !~ '^[0-9]{13}$') or (a->>'idType'='cedula' and a->>'id' !~ '^[0-9]{10}$')) then errs=array_append(errs,'id');end if;

 if a->>'person'='legal' then
 if jsonb_array_length(a->'owners')=0 and coalesce(a->>'ownershipExplanation','')='' then errs=array_append(errs,'ownershipExplanation');end if;
 for o in select value from jsonb_array_elements(a->'owners') loop
 if coalesce(o->>'name','')='' or coalesce(o->>'id','')='' or o->>'country' !~ '^[A-Z]{2}$' or length(o->>'name')>250 or length(o->>'id')>60 or not glf_kyc_private.related_id_valid(o->>'idType',o->>'id',o->>'country') then errs=array_append(errs,'owners');end if;
 if o->>'pct' !~ '^[0-9]+(\.[0-9]{1,2})?$' then errs=array_append(errs,'owners');else
 if (o->>'pct')::numeric<10 or (o->>'pct')::numeric>100 then errs=array_append(errs,'owners');end if;total=total+(o->>'pct')::numeric;end if;
 end loop;if total>100.001 then errs=array_append(errs,'owners');end if;end if;
 if a->>'person'='legal' and not glf_kyc_private.related_id_valid(a->>'legalRepIdType',a->>'legalRepId',a->>'legalRepCountry') then errs=array_append(errs,'legalRepId');end if;
 if a->>'person'='natural' and a->>'spouse'='yes' and not glf_kyc_private.related_id_valid(a->>'spouseIdType',a->>'spouseId',a->>'spouseCountry') then errs=array_append(errs,'spouseId');end if;
 return array(select distinct e from unnest(errs) e);
end;$$;



do $version$
declare fn regprocedure;definition text;
begin
 foreach fn in array array['public.glf_kyc_save(text,integer,jsonb)'::regprocedure,'public.glf_kyc_assist(uuid,integer,integer,text,jsonb,text,boolean,boolean)'::regprocedure] loop
  definition=pg_get_functiondef(fn);execute replace(definition,'2026-10-27.4','2026-10-27.5');
 end loop;
end;$version$;
notify pgrst,'reload schema';
commit;
